const unlockCoursewareUnitTables=JSON.parse(document.getElementById("courseware-unit-data").textContent);
if(unlockCoursewareUnitTables.length!==52){throw new Error("The unit data and courseware runtime have different versions");}


/* Classroom rendering for the full course, attached to the established stage. */
function coursePlainSource(text) {
 const digits="⁰¹²³⁴⁵⁶⁷⁸⁹";
 return String(text??"").replace(/\[IMAGE_\d+\]/gi,"")
  .replace(/\$(-?\d+(?:\.\d+)?)\\mathrm\{(km)\}\$/g,"$1 $2")
  .replace(/\$(-?\d+(?:\.\d+)?)\^\{\s*\\circ\s*\}\s*(?:\\mathrm\{([CF])\})?\$/g,
   (_,number,unit)=>number+(unit?" °"+unit:"°"))
  .replace(/\$((?:\d+ = )?\d+(?:\.\d+)?)\\%\$/g,"$1%")
  .replace(/ ?\$\^\{(\d{1,2})\}\$/g,(_,number)=>[...number].map(n=>digits[Number(n)]).join(""));
}

function courseText(text) {
 const html=esc(coursePlainSource(text).trim());
 return html.replace(/^\s*#{1,5}\s+(.+)$/,"<strong>$1</strong>")
  .replace(/\*\*([^*]+)\*\*/g,"<strong>$1</strong>")
  .replace(/&lt;(?:br)\s*\/?&gt;/gi,"<br>")
  .replace(/&lt;(\/?)(?:b|strong)&gt;/gi,"<$1strong>")
  .replace(/&lt;(\/?)(?:i|em)&gt;/gi,"<$1em>")
  .replace(/&lt;(\/?)u&gt;/gi,"<$1u>")
  .replace(/&amp;(nbsp|amp|lt|gt|quot|#39);/gi,"&$1;");
}

function courseOption(raw, index) {
 if(typeof raw==="string")return {label:String.fromCharCode(97+index),text:raw};
 return {
  label:String(raw.optionLabel??raw.label??String.fromCharCode(97+index)),
  text:String(raw.optionEn??raw.textEn??raw.option??raw.text??raw.optionLabel??"")
 };
}

