function courseReview(c) {
 return courseExerciseReviews[c.id.split(":").at(-1)];
}

function courseConfirmedRows(c) {
 const answer=c.courseAnswer;
 if(answer?.kind!=="teacher-excerpt"||!answer.text) return new Map();
 const items=c.coursePages.flat().filter(block=>block.kind==="item");
 if(!items.length||items.some((item,i)=>item.label!==String(i+1))) return new Map();
 const text=answer.text.replace(/\s+/g," ").trim();
 const truth=/\btrue\b.*\bfalse\b|T\s*\(true\)|F\s*\(false\)/i.test(c.instruction);
 const tokens=truth?[...text.matchAll(/(?:^|\s)(\d{1,2})[.)]?\s*(True|False|T|F)\b/gi)]:
  [...text.matchAll(/(?:^|\s)(\d{1,2})[.)]?\s*([a-z])(?=\s|$)/gi)];
 if(tokens.length!==items.length||tokens[0].index!==0||tokens.some((token,i)=>Number(token[1])!==i+1)) return new Map();
 const rows=[];
 for(const [i,token] of tokens.entries()){
  const value=token[2];
  const rest=text.slice(token.index+token[0].length,tokens[i+1]?.index??text.length).trim();
  if(truth) {
   const flag=value[0].toUpperCase();
   if(rest&&(flag!=="F"||!/^[;:.,-]\s*[A-Z]/.test(rest)||/\bExercise\b|\bBooklet\b/.test(rest))) return new Map();
   rows.push({mode:"status",answer:flag,correction:rest.replace(/^[;:.,-]\s*/,"")});
   continue;
  }
  if(rest) return new Map();
  const options=(items[i].options??[]).map(courseOption);
  const lower=value.toLowerCase();
  const explicit=options.findIndex(o=>String(o.text).trim().toLowerCase()===lower||
   o.label!==o.text&&String(o.label).trim().toLowerCase()===lower);
  const indexed=lower.charCodeAt(0)-97;
  const positional=/\b(?:choose|circle|select|tick)\b/i.test(c.instruction)&&indexed>=0&&indexed<options.length;
  if(explicit<0&&!positional) return new Map();
  rows.push({mode:"choice",option:explicit>=0?explicit:indexed});
 }
 return new Map(rows.map((row,i)=>[String(i+1),row]));
}

function coursePageBlocks(c,p) {
 const fix=courseReview(c);
 const page=c.coursePages[p];
 if(c.rewatchLayout)return page;
 if(!fix) {
  const answers=courseConfirmedRows(c);
  const additional=typeof coursePublishedAnswers!=="undefined"?coursePublishedAnswers[c.id]:null;
  if(!answers.size&&!additional) return page;
  const editsHere=(edits,index)=>edits?.filter(edit=>edit.part===p&&edit.block===index)??[];
  return page.flatMap((block,index)=>{
   if(editsHere(additional?.skipTextBlocks,index).length) return [];
   const replacement=editsHere(additional?.replaceBlocks,index)[0];
   if(replacement)return replacement.blocks;
   const table=editsHere(additional?.tableEdits,index);
   if(block.kind==="table"&&table.length) {
    const rows=block.rows.map((row,r)=>row.map((cell,x)=>{
     const answer=table.find(edit=>edit.row===r&&edit.cell===x);
     if(!answer)return cell;
     if(answer.values)return {...cell,text:answer.text,answer:{mode:"blanks",values:answer.values}};
     if(answer.parts)return {...cell,answer:{mode:"text-marks",parts:answer.parts}};
     if(answer.suffix)return {...cell,answer:{mode:"suffix",answer:answer.suffix}};
     if(answer.mark)return {...cell,answer:{mode:"mark"}};
     return {...cell,answer:{answer:answer.answer,showMarker:true}};
    }));
    return [{...block,rows}];
   }
   const fill=editsHere(additional?.textFills,index)[0];
   if(block.kind==="text"&&fill)return {...block,text:fill.text,answer:{mode:"blanks",values:fill.values}};
   const inline=editsHere(additional?.inlineEdits,index)[0];
   if(block.kind==="text"&&inline) return [{...block,answer:{mode:"text-replacements",values:inline.values}}];
   const planned=editsHere(additional?.textItems,index)[0];
   const item=planned?{...planned.item,kind:"item"}:block;
   if(item.kind!=="item") return [item];
   const verified=additional?.rows[item.id];
   const answer=(additional?.overrideRows&&verified?verified:item.answer)??verified??answers.get(item.label);
   const rendered={...item,...additional?.itemPatches?.[item.id]};
   if((additional?.overrideRows&&answer?.hideOptions)||answer?.omitGeneratedTruthOptions) rendered.options=[];
   return [answer&&!(answer.mode==="mark"&&answer.selected===false)?{...rendered,answer}:rendered];
  }).concat(additional?.appendBlocks?.flatMap(entry=>entry.part===p?entry.blocks:[])??[]);
 }
 const blocks=fix.textGroups?fix.textGroups[p].map(i=>c.coursePages[0][i]):[
  ...(p===0?fix.prefix??[]:[]), ...page, ...(p===c.coursePages.length-1?fix.tail??[]:[])
 ];
 return blocks.map(block=>{
  if(block.kind==="text") {
   const label=/^\s*(\d+)[.)]?\s/.exec(block.text)?.[1];
   const slots=[...block.text.matchAll(/\((\d+)\)\s+_{2,}/g)];
   if(fix.numberedNotes&&slots.length) {
    return {...block,answer:{mode:"blanks",values:slots.map(hit=>fix.numberedNotes[Number(hit[1])-1])}};
   }
   const values=fix.text?.[label];
   if(values?.length===[...block.text.matchAll(/_{2,}|□/g)].length) return {...block,answer:{mode:"blanks",values}};
   if(fix.single) return {...block,answer:{mode:"line",answer:fix.single}};
   return block;
  }
  if(block.kind!=="item") return block;
  const label=block.label;
  let answer=block.answer;
  if(fix.statuses?.[label]){
   const [value,correction]=fix.statuses[label];
   answer={mode:"status",answer:value,correction};
  } else if(Object.hasOwn(fix.choices??{},label)) answer={mode:"choice",option:fix.choices[label]};
  else if(fix.multi?.[label]) answer={mode:"blanks",values:fix.multi[label]};
  else if(fix.gaps?.[label]) answer={mode:"gap",answer:fix.gaps[label]};
  else if(fix.lines?.[label]) answer={mode:"line",answer:fix.lines[label]};
  else if(fix.example?.[label]) answer={mode:"example",answer:fix.example[label]};
  if(fix.marks?.includes(label))answer={mode:"mark"};
  return {...block,...(fix.patches?.[label]??{}),...(fix.hideChoices?{options:[]}:{}),answer};
 });
}

function courseFragment(text) {
 if(!text.trim())return esc(text);
 return esc(text.match(/^\s*/)[0])+courseText(text)+esc(text.match(/\s*$/)[0]);
}

function courseInlineParts(text, terms) {
 if(/<[^>]+>/.test(text))return null;
 const normalize=s=>s.replace(/[’‘]/g,"'");
 const seen=[];
 for(const [i,term] of terms.entries()){
  const key=normalize(term).replace(/[.*+?^${}()|[\]\\]/g,"\\$&");
  if(!key)return null;
  const hits=[...normalize(text).matchAll(new RegExp("(?<![\\p{L}\\p{N}])"+key+"(?![\\p{L}\\p{N}])","giu"))];
  if(hits.length!==1)return null;
  seen.push({start:hits[0].index,end:hits[0].index+hits[0][0].length,index:i});
 }
 seen.sort((a,b)=>a.start-b.start);
 return seen.some((x,i)=>i>0&&x.start<seen[i-1].end)?null:seen;
}

function courseMarkText(text, parts, correct) {
 let cursor=0, html="";
 for(const part of parts){
  html+=courseFragment(text.slice(cursor,part.start));
  const slice=text.slice(part.start,part.end);
  const content=part.inner?courseMarkText(slice,part.inner,part.inner.map(mark=>mark.index)):courseFragment(slice);
  const marker=(part.underline?' data-course-underline':'')+(part.circle?' data-course-circle':'');
  html+=correct.includes(part.index)?'<span data-course-correct-choice'+marker+'>'+content+'</span>':content;
  cursor=part.end;
 }
 return html+courseFragment(text.slice(cursor));
}

function courseFill(text,values,colors=[]) {
 const slots=[...text.matchAll(/_{2,}|□/g)];
 let html="", from=0;
 slots.forEach((slot,i)=>{
  const value=values[i];
  html+=courseFragment(text.slice(from,slot.index));
  if(value) html+='<span class="course-gap"><span data-course-answer-target'+(colors[i]? ' class="'+colors[i]+'"':"")+'>'+esc(value)+'</span></span>';
  else html+=courseText(slot[0]);
  from=slot.index+slot[0].length;
 });
 return html+courseFragment(text.slice(from));
}

function courseItemHTML(item) {
 const row=item.answer;
 const number='<span class="num">'+esc(item.label)+'</span>';
 const wideLabel=String(item.label).length>6;
 const mode=row?.mode;
 const slots=/<\/?[^>]+>/g.test(item.prompt)?[]:[...item.prompt.matchAll(/_{2,}|□/g)];
 let answerText=courseText(item.prompt), supplementary="";
 if(mode==="blanks"&&slots.length===row.values.length) answerText=courseFill(item.prompt,row.values);
 if(mode==="gap"&&slots.length===1) answerText=courseFill(item.prompt,[row.answer]);
 if(mode==="status"&&slots.length) answerText=courseFill(item.prompt,[row.answer,row.correction],["","course-correction"]);
 if(mode==="line"||mode==="gap"&&slots.length!==1||mode==="status"&&!slots.length) {
  supplementary='<span class="course-answer-value" data-course-answer-target>'+esc(row.answer)+'</span>';
 }
 if(mode==="status"&&row.correction&&slots.length<2) supplementary+='<span class="course-correction" data-course-answer-target>'+esc(row.correction)+'</span>';
 if(mode==="example") supplementary='<span class="course-example-result">'+esc(row.answer)+'</span>';
 let options=mode==="status"||mode==="indexed-mark"?[]:(item.options??[]).map(courseOption);
 const correct=mode==="choice"?(row.options??[row.option]):[];
 if(options.length>1&&(!mode||mode==="choice")){
  const inline=courseInlineParts(item.prompt,options.map(opt=>opt.text));
  if(inline){
   answerText=courseMarkText(item.prompt,inline,correct);
   options=[];
  }
 }
 if(mode==="indexed-mark"){
  answerText=courseMarkText(item.prompt,row.parts.map((part,index)=>({...part,index})),row.parts.map((_,index)=>index));
 }
 if(mode==="token-marks"){
  const inline=courseInlineParts(item.prompt,row.tokens);
  if(inline)answerText=courseMarkText(item.prompt,inline,row.tokens.map((_,i)=>i));
  else supplementary='<span class="course-answer-value" data-course-answer-target>'+esc(row.tokens.join(", "))+'</span>';
 }
 if(row?.note) supplementary+='<span class="course-answer-note" data-course-answer-target>'+esc(row.note)+'</span>';
 const inlineLabel=options.some(o=>o.label&&o.label!==o.text);
 const optionHtml=options.length?'<ol class="course-options course-option-labels'+(options.length>2&&!item.stackOptions?' course-options-grid':'')+'">'+
  options.map((option,i)=>'<li'+(correct.includes(i)?' data-course-correct-choice':'')+'>'+
    (inlineLabel?'<span class="course-option-label">'+esc(option.label)+'</span>':"")+
    '<span>'+courseText(option.text)+'</span></li>').join("")+'</ol>':"";
 return '<div class="course-item'+(wideLabel?' course-item-wide-label':'')+'">'+number+'<div>'+
  '<p'+(item.dialogue?' class="course-dialogue"':"")+(mode==="mark"?' data-course-correct-choice':"")+'>'+answerText+supplementary+'</p>'+optionHtml+'</div></div>';
}

function courseBlockHTML(block) {
 if (block.kind==="task-figure") {
  const [,,width,height]=block.photo.box;
  const style='width:min(100%,'+block.width+'px);aspect-ratio:'+width+'/'+height;
  return '<figure class="course-inline-task-figure" style="'+style+'">'+cropHTML(block.photo)+'</figure>';
 }
 if (block.kind==="item") return courseItemHTML(block);
 if(block.kind==="rewatch-options"){
  return '<ol type="a" class="course-shared-options">'+block.options.map(option=>
   '<li>'+courseText(option.text)+'</li>').join("")+'</ol>';
 }
 if(block.kind==="rewatch-notes"){
  return '<ul class="course-student-notes">'+block.notes.map(note=>
   '<li>'+courseFill(note.text,[note.answer])+'</li>').join("")+'</ul>';
 }
 if (block.kind==="figure-grid") {
  const figures=block.figures.map(({photo,item})=>'<figure>'+cropHTML(photo)+
   '<figcaption>'+courseItemHTML(item)+'</figcaption></figure>').join("");
  return '<div class="course-figure-grid" style="--course-figure-cols:'+block.columns+'">'+figures+'</div>';
 }
 if (block.kind==="figure-answer-labels") {
  const fields=block.fields.map(field=>'<span class="course-chart-answer-label" data-course-answer-target style="left:'+
   field.left+'%;top:'+field.top+'%">'+esc(field.answer)+'</span>').join("");
  return '<div class="course-chart-answers"'+(block.clip?' style="clip-path:polygon('+esc(block.clip)+')"':'')+'>'+cropHTML(block.photo,fields)+'</div>';
 }
 if (block.kind==="figure-chart") {
  const [left,top,width,height]=block.outline;
  const outline='<span data-course-correct-choice class="course-figure-highlight" style="left:'+left+
   '%;top:'+top+'%;width:'+width+'%;height:'+height+'%"></span>';
  return '<div class="course-chart-options">'+cropHTML(block.photo,outline)+'</div>';
 }
 if (block.kind==="table") {
  const cols=block.columnWidths?.map(width=>'<col style="width:'+width+'%">').join("");
  return '<div class="course-table-frame"><table class="course-table'+(cols?' course-table-arranged':'')+'">'+
   (cols?'<colgroup>'+cols+'</colgroup>':"")+'<tbody>'+
   block.rows.map(row=>'<tr>'+row.map(({text,header,colspan,rowspan,answer})=>{
    const tag=header?"th":"td";
    const span=(Number.isInteger(colspan)&&colspan>1?' colspan="'+colspan+'"':"")+
     (Number.isInteger(rowspan)&&rowspan>1?' rowspan="'+rowspan+'"':"");
    let content=courseText(text);
    if(answer?.mode==="blanks")content=courseFill(text,answer.values);
    else if(answer?.mode==="text-marks"){
     const parts=answer.parts.map((part,index)=>({...part,index}));
     content=courseMarkText(text,parts,parts.map(part=>part.index));
    }
    else if(answer?.mode==="suffix")content+='<span data-course-answer-target>'+esc(answer.answer)+'</span>';
    else if(answer&&answer.mode!=="mark")content=(answer.showMarker&&content?content+" ":"")+
     '<span class="course-gap"><span data-course-answer-target>'+esc(answer.answer)+'</span></span>';
    return '<'+tag+span+(answer?.mode==="mark"?' data-course-correct-choice':'')+'>'+content+'</'+tag+'>';
   }).join("")+'</tr>').join("")+'</tbody></table></div>';
 }
 let body=block.answer?.mode==="blanks"?courseFill(block.text,block.answer.values):courseText(block.text);
 if(block.answer?.mode==="text-marks"){
  const parts=block.answer.parts.map((part,index)=>({...part,index}));
  body=courseMarkText(block.text,parts,parts.map(part=>part.index));
 }
 if(block.answer?.mode==="text-replacements"){
  let from=0;
  body="";
  for(const {end,answer} of block.answer.values){
   body+=courseFragment(block.text.slice(from,end))+'<span data-course-answer-target class="course-rewrite-value">'+esc(answer)+'</span>';
   from=end;
  }
  body+=courseFragment(block.text.slice(from));
 }
 return (body?'<p class="course-copy">'+body+'</p>':"")+
  (block.answer?.mode==="line"?'<p class="course-line-answer"><span data-course-answer-target>'+esc(block.answer.answer)+'</span></p>':"");
}

