function reviseCourseVocabulary(data) {
 if(typeof courseLexemeReviews==="undefined")return;
 for(const entry of data.lessonFlow?.entries??[]){
  const kind=entry.flow.kind;
  if(kind==="cards"){
   for(const word of entry.flow.pages.flat()){
    const revision=courseLexemeReviews[word.id];
    if(word.id==="B02-RW-U08-W-100ec4462"&&word.definition==="somebody that makes you believe something is true") {
     word.definition="something that makes you believe something is true";
    }
    if(!revision)continue;
    word.example=revision.example;
    word.exampleMark=revision.mark;
    word.exampleVoice={set:"revised-example",key:word.id};
    if(revision.visual)word.visual=revision.visual;
   }
   continue;
  }
  if(!["match","use"].includes(kind))continue;
  const checks=new Map((entry.feedback?.rows??[]).map(row=>[row.label,row]));
  for(const page of entry.flow.pages){
   for(const row of page.rows){
    const revision=courseLexemeReviews[row.id];
    if(!revision)continue;
    const feedback=checks.get(row.label);
    row.basis=revision.example;
    if(feedback)feedback.basis=revision.example;
    if(kind==="match"){
     row.prompt=revision.example;
     const i=row.answer.charCodeAt(0)-65;
     if(revision.visual&&i>=0&&i<page.visuals.length)page.visuals[i]=revision.visual;
    } else {
     const index=revision.example.indexOf(revision.mark);
     const bankIndex=page.bank.indexOf(row.answer);
     if(bankIndex>=0)page.bank[bankIndex]=revision.mark;
     row.before=revision.example.slice(0,index);
     row.after=revision.example.slice(index+revision.mark.length);
     row.answer=revision.mark;
     if(feedback)feedback.answer=revision.mark;
    }
   }
  }
  if(kind==="match"&&entry.flow.pages.every(page=>page.visuals.every(v=>v.src))){
   entry.instruction="Match each sentence to the correct picture.";
  }
 }
}

