function courseSharedRewatchOptions(blocks) {
 const options=blocks[0]?.options?.map(courseOption);
 if(!options?.length)return null;
 const sameOptions=block=>block.options?.length===options.length&&
  block.options.map(courseOption).every((option,i)=>option.label===options[i].label&&option.text===options[i].text);
 if(!blocks.every(block=>block.kind==="item"&&sameOptions(block)&&
  block.answer?.mode==="choice"&&options[block.answer.option]))return null;
 const items=blocks.map(block=>({
  ...block, prompt:block.prompt+" ____", options:[],
  answer:{mode:"gap",answer:options[block.answer.option].label}
 }));
 return [...items,{kind:"rewatch-options",options}];
}

function courseRewatchNotes(blocks) {
 const notes=blocks.filter(block=>block.kind==="text");
 const items=blocks.filter(block=>block.kind==="item");
 if(!notes.length||notes.length!==items.length||notes.length+items.length!==blocks.length)return null;
 const indexed=new Map(items.map(item=>[item.label,item]));
 const normalize=text=>text.replace(/\(\d+\)\s+(?=_{2,})/g,"").replace(/_{2,}/g,"____").trim();
 const aligned=notes.map(note=>{
  const match=/^-\s+(.*(\(\d+\))\s+_{2,}.*)$/.exec(note.text);
  const item=indexed.get(match?.[2]);
  if(!match||item?.answer?.mode!=="gap"||!item.answer.answer||normalize(match[1])!==normalize(item.prompt))return null;
  return {text:match[1],answer:item.answer.answer};
 });
 return aligned.every(Boolean)?[{kind:"rewatch-notes",notes:aligned}]:null;
}

function reviseCoursePhotoMatching(model) {
 const c=model.byId.get("B01-LS-U01-question:b744");
 if(!c?.coursePages)return;
 const blocks=c.coursePages.flatMap((_,p)=>coursePageBlocks(c,p));
 const items=blocks.filter(block=>block.kind==="item");
 if(items.length!==4||!items.every(item=>item.answer?.mode==="choice"&&/^[1-4]$/.test(item.options?.[item.answer.option]??"")))return;
 const plain=text=>text.replace(/[–—]/g,"-").replace(/\s+/g," ").trim();
 const duplicates=blocks.filter(block=>block.kind!=="item");
 if(!duplicates.every(block=>block.kind==="text"&&(plain(block.text)===plain(c.ex+" "+c.instruction)||
  items.some(item=>plain(block.text)===plain(item.label+" "+item.prompt)))))return;
 c.coursePages=[items.map(item=>({...item,prompt:item.prompt+" ____",options:[],
  answer:{mode:"gap",answer:item.options[item.answer.option]}}))];
 c.rewatchLayout={split:0};
}

function reviseCourseRewatch(model) {
 for(const [id,plan] of Object.entries(courseRewatchPlans)){
  const c=model.byId.get(id);
  if(!(c?.coursePages?.length>1)||c.courseVisuals?.length||
   courseReview(c)?.photos?.length||coursePublishedAnswers[c.id]?.photos?.some(Boolean))continue;
  const blocks=c.coursePages.flatMap((_,p)=>coursePageBlocks(c,p));
  let revised=blocks, split=plan;
  if(plan==="shared-options"){
   revised=courseSharedRewatchOptions(blocks);
   split=blocks.length;
  } else if(plan==="notes"){
   revised=courseRewatchNotes(blocks);
   split=0;
  }
  if(!revised?.length)continue;
  c.coursePages=[revised];
  c.rewatchLayout={split,sharedOptions:plan==="shared-options"};
 }
}

