const courseWordPictures=unlockCoursewareUnitTables[2];
function bindCourseCardPictures(data) {
 if (typeof courseWordPictures==="undefined") return;
 const words=[];
 for (const entry of data.lessonFlow?.entries??[]) {
  if (entry.flow?.kind!=="cards") continue;
  for (const word of entry.flow.pages.flat()) {
   const visual=courseWordPictures[word.id];
   if (visual) word.visual=visual;
   words.push(word);
  }
 }
 const byId=new Map(words.map(word=>[word.id,word]));
 const photoKey=v=>v.src+"|"+(v.box?.join(",")??"");
 for (const entry of data.lessonFlow?.entries??[]) {
  if (entry.flow?.kind!=="match") continue;
  for (const page of entry.flow.pages) {
   const answers=new Set();
   for (const row of page.rows) {
    const index=row.answer.charCodeAt(0)-65;
    if (index<0||index>=page.visuals.length) continue;
    answers.add(index);
    const specific=byId.get(row.id)?.visual;
    if (specific?.src) page.visuals[index]=specific;
   }
   const used=new Set(page.visuals.filter(v=>v.src).map(photoKey));
   for (const [i,visual] of page.visuals.entries()) {
    if (answers.has(i)||visual.src) continue;
    const candidate=words.find(w=>w.definition===visual.lines?.join("\n")&&w.visual?.src&&!used.has(photoKey(w.visual)));
    if (candidate) {
     page.visuals[i]=candidate.visual;
     used.add(photoKey(candidate.visual));
    }
   }
   if (page.visuals.every(v=>v.src)&&new Set(page.visuals.map(photoKey)).size!==page.visuals.length) {
    throw new Error(entry.id+" 图片选项重复");
   }
  }
  if (entry.flow.pages.every(page=>page.visuals.every(visual=>visual.src))) {
   entry.instruction="Match each sentence to the correct picture.";
  }
 }
}

buildClassroomModel=function(data) {
 for(const item of data.fixtures??[]){
  const activePages=coursePublishedAnswers[item.id]?.displayPages;
  if(activePages)item.coursePages=activePages;
  const reviewed=coursePublishedAnswers[item.id];
  if(reviewed?.materials)item.courseMaterials=reviewed.materials;
  if(reviewed?.visuals)item.courseVisuals=reviewed.visuals;
 }
  for(const entry of data.lessonFlow?.entries??[]){
   const pages=courseReadingPagination[entry.id];
   if(pages)entry.flow.pages=revisedCourseReadingScreens(entry,pages);
  }
  reviseCourseVocabulary(data);
  bindCourseCardPictures(data);
 prepareClassroomVideo(data);
 prepareClassroomVocabulary(data);
 prepareCourseOriginalReadings(data);
 prepareCourseObjectives(data);
 const model=courseBaseModel(data);
 const findSource=model.source;
 model.source=(c,page)=>{
  const existing=findSource(c,page);
  const originalKey=courseOriginalKey(c,page);
  if (!courseOriginalPages.pages[originalKey]) return existing;
  return {...existing,originalKey,book:model.bookNumber(c),track:c.track,page:Number(page),pdf:courseOriginalPdfLink(originalKey)};
 };
 const header=model.header;
 model.header=c=>c.module==="UNLOCK YOUR KNOWLEDGE"?{...header(c),activity:""}:header(c);
 reviseCourseRewatch(model);
 reviseCoursePhotoMatching(model);
 return model;
};

