function fitCourseCaption(line) {
 line.style.removeProperty("font-size");
 if (!line.textContent || !line.clientHeight) return;
 let size=parseFloat(line.ownerDocument.defaultView.getComputedStyle(line).fontSize);
 while (line.scrollHeight>line.clientHeight+1 && size>12) {
  size=Math.max(12,size-1);
  line.style.fontSize=size+"px";
 }
}

function setCourseCinemaWindow(doc,shell,enabled) {
 if (enabled && !document.getElementById("course-cinema-window-style")) {
  const style = document.createElement("style");
  style.id = "course-cinema-window-style";
  style.textContent = '#preview.course-cinema-window{position:fixed!important;inset:0!important;'+
   'width:100vw!important;height:100vh!important;transform:none!important;z-index:2147483647!important}';
  document.head.append(style);
 }
 shell.classList.toggle("course-cinema-fill",enabled);
 doc.defaultView.frameElement?.classList.toggle("course-cinema-window",enabled);
}

function courseProofVideo(doc,c) {
 if (!c.classroomVideoProof) return null;
 return {type:"video",open:time=>openCourseCinema(doc,c,time)};
}

async function openCourseCinema(doc,c,seekTime) {
 const videoIndex = classroom.indexById.get(c.classroomVideoId);
 if (videoIndex === undefined) return;
 const review = doc.querySelector("[data-course-reveal]");
 const inlineProof = doc.querySelector("#inline-proof:not([hidden]) #inline-proof-title");
 const resume = courseCinema.resume;
 courseCinema.origin = {
  id:c.id,index:current,page:part,videoId:c.classroomVideoId,
  reviewCount:Number(review?.dataset.u6ReviewSteps ?? (review?.getAttribute("aria-pressed") === "true" ? 1 : 0)),
  inlineCount:doc.querySelectorAll("[data-inline-item][data-inline-shown]").length,
  proofTitle:inlineProof?.textContent,
  fromProof:Number.isFinite(seekTime),
  time:seekTime ?? (resume?.id === c.id && resume.page === part ? resume.time : 0)
 };
 await display(videoIndex,0);
 if (cases[current]?.id === c.classroomVideoId) {
  frame.contentDocument?.querySelector(".course-cinema-picture video")?.focus({preventScroll:true});
 }
}

async function returnFromCourseCinema(doc,region,player,origin) {
 if (!origin || courseCinema.origin !== origin) return;
 player.pause();
 courseCinema.resume = {id:origin.id,page:origin.page,time:player.ended ? 0 : player.currentTime};
 courseCinema.origin = null;
 if (doc.fullscreenElement) {
  try { await doc.exitFullscreen(); } catch {}
 }
 setCourseCinemaWindow(doc,region.closest(".shell"),false);
 await display(origin.index,origin.page);
 if (cases[current]?.id !== origin.id || part !== origin.page) return;
 const question = frame.contentDocument;
 const review = question.querySelector("[data-course-reveal]");
 for (let step=0; step<origin.reviewCount; step++) review?.click();
 const inline = question.querySelector("[data-inline-check]");
 for (let step=0; step<origin.inlineCount; step++) inline?.click();
 if (origin.proofTitle) {
  question.querySelector("[data-inline-evidence]")?.click();
  const title = question.querySelector("#inline-proof-title");
  const previous = question.querySelector("[data-inline-proof-prev]");
  for (let step=1; step<origin.inlineCount && title?.textContent!==origin.proofTitle; step++) previous?.click();
  question.querySelector("[data-proof-time]")?.focus({preventScroll:true});
 } else {
  question.querySelector("[data-course-unit-video]")?.focus({preventScroll:true});
 }
}

function wireCourseCinema(doc,c) {
 const region = doc.querySelector(".course-unit-video");
 doc.defaultView.frameElement?.classList.remove("course-cinema-window");
 if (!region) {
  courseCinema.origin = null;
  if (courseCinema.resume?.id !== c.id || courseCinema.resume.page !== part) courseCinema.resume = null;
  const trigger = doc.querySelector("[data-course-unit-video]");
  if (trigger) trigger.onclick = () => openCourseCinema(doc,c);
  return false;
 }

 const shell = region.closest(".shell");
 const player = region.querySelector("video");
 const english = region.querySelector('[data-course-video-caption="en"]');
 const chinese = region.querySelector('[data-course-video-caption="zh"]');
 const toggles = [...doc.querySelectorAll("[data-course-video-chinese]")];
 const fullscreens = [...doc.querySelectorAll("[data-course-video-fullscreen]")];
 const origin = courseCinema.origin?.videoId === c.id ? courseCinema.origin : null;
 const cues = c.classroomVideo.cues;
 if (!origin) courseCinema.resume = null;
 let showChinese = false;

 function refresh() {
  const time = player.currentTime;
  const cue = cues.find(row => row[0] <= time && time < row[1]);
  const en = cue?.[2] ?? "";
  const zh = showChinese ? cue?.[3] ?? "" : "";
  if (english.textContent !== en) {
   english.textContent = en;
   fitCourseCaption(english);
  }
  if (chinese.textContent !== zh) {
   chinese.textContent = zh;
   fitCourseCaption(chinese);
  }
 }

 for (const event of ["loadedmetadata","timeupdate","seeking","seeked","play","pause","ended"]) {
  player.addEventListener(event,refresh);
 }
 const captionResize=new ResizeObserver(() => {
  fitCourseCaption(english);
  fitCourseCaption(chinese);
 });
 captionResize.observe(region.querySelector(".course-cinema-captions"));
 doc.defaultView.addEventListener("pagehide",() => captionResize.disconnect(),{once:true});
 if (typeof player.requestVideoFrameCallback === "function") {
  let requested = null;
  function stop() {
   if (requested !== null) player.cancelVideoFrameCallback(requested);
   requested = null;
  }
  function schedule() {
   if (requested !== null || player.paused || player.ended) return;
   requested = player.requestVideoFrameCallback(() => {
    requested = null;
    refresh();
    schedule();
   });
  }
  player.addEventListener("playing",schedule);
  player.addEventListener("seeked",schedule);
  player.addEventListener("pause",stop);
  player.addEventListener("ended",stop);
  doc.defaultView.addEventListener("pagehide",stop,{once:true});
 }

 if (origin?.time > 0 || origin?.fromProof) {
  const restore = () => {
   player.currentTime = Math.min(origin.time,Math.max(0,player.duration-.05));
   if (origin.fromProof) player.play().catch(()=>{});
  };
  if (player.readyState >= 1) restore();
  else player.addEventListener("loadedmetadata",restore,{once:true});
 }
 player.addEventListener("error",() => {
  const status = region.querySelector("[data-course-video-error]");
  status.textContent = "视频加载失败。";
  status.hidden = false;
 });
 for (const toggle of toggles) {
  toggle.onclick = () => {
   showChinese = !showChinese;
   for (const control of toggles) control.setAttribute("aria-pressed",String(showChinese));
   refresh();
  };
 }

 function syncFullscreenButtons() {
  const full = Boolean(doc.fullscreenElement) || shell.classList.contains("course-cinema-fill");
  for (const button of fullscreens) button.textContent = full ? "退出全屏" : "全屏";
 }
 function fillWindow(enabled) {
  setCourseCinemaWindow(doc,shell,enabled);
  syncFullscreenButtons();
 }
 doc.addEventListener("fullscreenchange",syncFullscreenButtons);
 for (const control of fullscreens) control.onclick = async () => {
  if (shell.classList.contains("course-cinema-fill")) fillWindow(false);
  else if (doc.fullscreenElement) await doc.exitFullscreen();
  else {
   try { await shell.requestFullscreen({navigationUI:"hide"}); }
   catch { fillWindow(true); }
  }
 };
 doc.addEventListener("keydown",event => {
  if (event.key === "Escape" && shell.classList.contains("course-cinema-fill")) {
   event.preventDefault();
   event.stopImmediatePropagation();
   fillWindow(false);
  }
 },true);
 for (const control of doc.querySelectorAll("[data-course-video-return]")) {
  control.onclick = () => returnFromCourseCinema(doc,region,player,origin);
 }
 refresh();
 return true;
}

function prepareClassroomVocabulary(data) {
 for (const entry of data.lessonFlow?.entries ?? []) {
  const pages = classroomVocabularyData.boxes[entry.id];
  if (!pages) continue;
  entry.exerciseVocabulary = pages;
  entry.flow.pages = pages.map(rows => rows.map(row =>
   [row.term,row.pos,row.definition].filter(Boolean).join(" ")));
 }
}

