// The source viewer resolves the printed page to its student-book PDF or the original scan.
const coursePdfRoot=new URL("../pdf-runtime/",document.currentScript.src);
const coursePdfBooks=new Map();
const courseRenderedPages=new Map();
const coursePageRequests=new WeakMap();
let coursePdfModule;

function courseOriginalKey(c,page) {
 return (typeof c==="string"?c:c.id).match(/^B\d{2}-(?:LS|RW)/)?.[0]+"/"+page;
}

function courseOriginalPdfLink(key) {
 const record=courseOriginalPages.pages[key];
 const volume=courseOriginalPages.volumes[key.split("/")[0]];
 return record?.pdf&&volume ? new URL(volume.src,document.baseURI).href+"#page="+record.pdf : "";
}

async function openCoursePdf(volume) {
 coursePdfModule??=import(new URL("build/pdf.min.mjs",coursePdfRoot).href);
 const pdf=await coursePdfModule;
 pdf.GlobalWorkerOptions.workerSrc=new URL("build/pdf.worker.min.mjs",coursePdfRoot).href;
 const url=new URL(volume.src,document.baseURI).href;
 const options={
  disableAutoFetch:true,disableStream:true,isEvalSupported:false,useSystemFonts:true,
  enableXfa:false,standardFontDataUrl:new URL("standard_fonts/",coursePdfRoot).href,
  wasmUrl:new URL("wasm/",coursePdfRoot).href,iccUrl:new URL("iccs/",coursePdfRoot).href
 };
 const fetchRange=(begin,end,signal)=>fetch(url,{headers:{Range:"bytes="+begin+"-"+(end-1)},signal});
 const initialEnd=Math.min(volume.size,262144);
 const initial=await fetchRange(0,initialEnd);
 if (!initial.ok) throw new Error("Student book did not load");
 const data=new Uint8Array(await initial.arrayBuffer());
 if (initial.status===200) {
  if (data.length!==volume.size) throw new Error("Incomplete student book");
  return pdf.getDocument({...options,data}).promise;
 }
 if (initial.status!==206||data.length!==initialEnd) throw new Error("Unexpected student book range");
 const stop=new AbortController();
 const range=new pdf.PDFDataRangeTransport(volume.size,data,true);
 let fail;
 const rangeFailure=new Promise((_,reject)=>{fail=reject});
 range.abort=()=>stop.abort();
 range.requestDataRange=(begin,end)=>{
  fetchRange(begin,end,stop.signal).then(async response=>{
   if (response.status!==206) throw new Error("Student book range unavailable");
   const bytes=new Uint8Array(await response.arrayBuffer());
   if (bytes.length!==end-begin) throw new Error("Incomplete student book range");
   range.onDataRange(begin,bytes);
  }).catch(error=>{if(!stop.signal.aborted)fail(error)});
 };
 const task=pdf.getDocument({...options,range,rangeChunkSize:262144});
 try {
  const book=await Promise.race([task.promise,rangeFailure]);
  return {book,rangeFailure};
 } catch (error) {
  await task.destroy();
  throw error;
 }
}

async function renderCourseOriginalPage(key) {
 const record=courseOriginalPages.pages[key];
 if (!record) throw new Error("Student book page not indexed");
 if (record.src) return new URL(record.src,document.baseURI).href;
 const tag=key.split("/")[0];
 if (!coursePdfBooks.has(tag)) {
  const opening=openCoursePdf(courseOriginalPages.volumes[tag]).catch(error=>{
   coursePdfBooks.delete(tag);
   throw error;
  });
  coursePdfBooks.set(tag,opening);
 }
 const book=await coursePdfBooks.get(tag);
 const openPage=(book.book??book).getPage(record.pdf);
 const page=await (book.rangeFailure ? Promise.race([openPage,book.rangeFailure]) : openPage);
 const viewport=page.getViewport({scale:2048/page.getViewport({scale:1}).width});
 const canvas=document.createElement("canvas");
 canvas.width=Math.ceil(viewport.width);
 canvas.height=Math.ceil(viewport.height);
 const paint=page.render({canvas,viewport,annotationMode:0}).promise;
 await (book.rangeFailure ? Promise.race([paint,book.rangeFailure]) : paint);
 return canvas.toDataURL("image/png");
}

function courseOriginalPageImage(key,label,linked=false) {
 const pdf=courseOriginalPdfLink(key);
 const source=courseOriginalPages.pages[key]?.src;
 const image='<img data-course-original-key="'+esc(key)+'" alt="'+esc(label)+'" hidden>';
 const link=pdf||source;
 return '<figure class="course-source-figure course-original-page">'+
  (linked&&link?'<a href="'+esc(new URL(link,document.baseURI).href)+'" target="_blank" rel="noopener" aria-label="'+esc(label)+'">'+image+'</a>':image)+
  '<p class="course-page-status" data-course-original-status role="status">正在加载教材原页。</p></figure>';
}

function displayCourseOriginalImage(image,key,status) {
 const request={key};
 coursePageRequests.set(image,request);
 image.hidden=true;
 status.hidden=false;
 status.textContent="正在加载教材原页。";
 let data=courseRenderedPages.get(key);
 if (!data) {
  data=renderCourseOriginalPage(key).catch(error=>{
   courseRenderedPages.delete(key);
   throw error;
  });
  courseRenderedPages.set(key,data);
  if(courseRenderedPages.size>8)courseRenderedPages.delete(courseRenderedPages.keys().next().value);
 }
 return data.then(async url=>{
  if (coursePageRequests.get(image)!==request||!image.isConnected) return;
  image.src=url;
  await image.decode();
  if (coursePageRequests.get(image)!==request||!image.isConnected) return;
  image.hidden=false;
  status.hidden=true;
 }).catch(()=>{
  if (coursePageRequests.get(image)!==request||!image.isConnected) return;
  status.textContent="教材原页加载失败。";
 });
}

function wireCourseOriginalPages(doc) {
 const observer=new doc.defaultView.IntersectionObserver(entries=>{
  for (const entry of entries) {
   if (!entry.isIntersecting) continue;
   const figure=entry.target;
   const image=figure.querySelector("[data-course-original-key]");
   observer.unobserve(figure);
   displayCourseOriginalImage(image,image.dataset.courseOriginalKey,figure.querySelector("[data-course-original-status]"));
  }
 });
 for (const figure of doc.querySelectorAll(".course-original-page")) observer.observe(figure);
 doc.defaultView.addEventListener("pagehide",()=>observer.disconnect(),{once:true});
}

function prepareCourseOriginalReadings(data) {
 for (const entry of data.lessonFlow?.entries??[]) {
  if (entry.flow?.kind!=="reading") continue;
  const reading=entry.readingView&&data.readings?.[entry.readingView.reading];
  const sections=entry.flow.pages??reading?.pages??[];
  const printed=sections.map(page=>page.sourcePage).filter(Number.isInteger);
  const pages=[...new Set(printed.length?printed:entry.pages)];
  if (!pages.length) continue;
  entry.flow.pages=pages.map(sourcePage=>({sourcePage}));
  entry.sourcePages??=entry.pages;
  entry.pages=pages;
 }
}

function courseOriginalReadingHTML(c,page) {
 const key=courseOriginalKey(c,page);
 return '<div class="course-original-reading">'+courseOriginalPageImage(key,"教材第 "+page+" 页")+'</div>';
}

