const courseObjectivesIndex = unlockCoursewareUnitTables[51];

const courseObjectivesTitle = "OBJECTIVES REVIEW";

function prepareCourseObjectives(data) {
 const lessonFlow = data.lessonFlow;
 const lastLesson = lessonFlow?.lessons.find(lesson => lesson.lesson === 2);
 const step = lastLesson?.steps.at(-1);
 const review = lessonFlow?.entries.find(entry => entry.id === step?.id);
 if (!review || review.flow?.kind !== "word-review") return;

 const unit = review.id.split("-classroom:")[0];
 const layout = courseObjectivesIndex[unit];
 if (!layout || review.pages[0] !== layout.page) return;

 const context = {moduleLabel: courseObjectivesTitle, phaseTitle: ""};
 review.module = courseObjectivesTitle;
 review.context = context;
 review.instruction = courseObjectivesTitle;
 review.flow = {kind: "objectives-review", pages: [layout]};
 Object.assign(step, {kind: "resource", label: courseObjectivesTitle, context});
}


function courseObjectivesNativeHTML(c, p) {
 const entry = c.flow.pages[p];
 const [first, second] = entry.numbers;
 const reviewRow = (number, text) => '<p class="objectives-prompt"><span class="objective-number">' +
  esc(number) + '</span><span>' + text + '</span></p>';
 const goals = entry.goals.map(goal => '<li><span class="objective-goal">' + esc(goal) +
  '</span><span class="objective-blank" aria-hidden="true"></span></li>').join("");
 const marker = '<span class="objectives-frequency" role="img" aria-label="High-frequency word"></span>';
 const list = entry.columns.map(column => '<ul>' + column.map(({word, pos, high}) =>
  '<li><span class="objectives-word">' + esc(word) + '</span>' +
  (pos || high ? ' <span class="objectives-word-details">' + esc(pos) + (pos && high ? " " : "") +
   (high ? marker : "") + '</span>' : "") + '</li>').join("") + '</ul>').join("");
 return '<section class="course-objectives-native" data-book="' + esc(c.book) + '" lang="en-GB">' +
  '<section class="objectives-self-check">' +
  '<h2 data-original-instruction>' + courseObjectivesTitle + '</h2>' +
  reviewRow(first, "Check your learning objectives for this unit. Write 3, 2 or 1 for each objective.") +
  '<div class="objectives-goal-body"><div class="objectives-scale"><span>3 = very well</span><span>2 = well</span><span>1 = not so well</span></div>' +
  '<p class="objectives-lead"><strong><em>I can ...</em></strong></p><ul class="objectives-goals">' + goals + '</ul></div>' +
  reviewRow(second, "Use the <em>Unlock</em> Digital Workbook for more practice with this unit’s learning objectives.") +
  '</section><section class="objectives-wordlist"><h2>WORDLIST</h2>' +
  '<div class="objectives-word-columns">' + list + '</div><p class="objectives-legend">' +
  marker + '<span>= high-frequency words in the Cambridge Academic Corpus</span></p></section></section>';
}


const courseInstructionWithoutObjectives = instructionHTML;
instructionHTML = function(c, showNumber) {
 if (c.flow?.kind === "objectives-review") return "";
 return courseInstructionWithoutObjectives(c, showNumber);
};
